import crypto from 'node:crypto';
import express from 'express';
import Redis from 'ioredis';

const app = express();
app.use(express.json({ verify: (req: any, _res, buf) => { req.rawBody = buf.toString('utf8'); } }));

const redis = new Redis(process.env.REDIS_URL!);
const CHATWOOT_URL = process.env.CHATWOOT_BASE_URL!; // vi du: https://inbox.company.vn
const CHATWOOT_API_TOKEN = process.env.CHATWOOT_USER_API_TOKEN!;
const CHATWOOT_ACCOUNT_ID = process.env.CHATWOOT_ACCOUNT_ID || '1';
const CHATWOOT_ZALO_INBOX_ID = Number(process.env.CHATWOOT_ZALO_INBOX_ID);
const ZALO_OA_SECRET = process.env.ZALO_OA_SECRET_KEY!;

function verifyZaloSignature(req: any): boolean {
  const sig = req.header('X-ZEvent-Signature') || '';
  const appId = req.body?.app_id || '';
  const ts = req.body?.timestamp || '';
  const payload = `${appId}${req.rawBody}${ts}${ZALO_OA_SECRET}`;
  const expected = 'mac=' + crypto.createHash('sha256').update(payload).digest('hex');
  return sig.length === expected.length && crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected));
}

app.post('/webhooks/zalo-oa', async (req, res) => {
  if (!verifyZaloSignature(req)) return res.status(401).json({ error: 'Invalid Zalo MAC' });
  const { event_name, sender, message, timestamp } = req.body;
  if (event_name !== 'user_send_text' || !message?.msg_id) return res.sendStatus(200);

  // Chong xu ly trung lap khi Zalo retry webhook
  const dedupOk = await redis.set(`zalo:msg:${message.msg_id}`, '1', 'EX', 86400, 'NX');
  if (!dedupOk) return res.sendStatus(200);

  // 1. Tim hoac tao Contact trong Chatwoot theo identifier zalo:<user_id>
  const contactRes = await fetch(`${CHATWOOT_URL}/api/v1/accounts/${CHATWOOT_ACCOUNT_ID}/contacts/search?q=${sender.id}`, {
    headers: { api_access_token: CHATWOOT_API_TOKEN },
  });
  const searchJson: any = await contactRes.json();
  let contactId = searchJson?.payload?.[0]?.id;

  if (!contactId) {
    const created = await fetch(`${CHATWOOT_URL}/api/v1/accounts/${CHATWOOT_ACCOUNT_ID}/contacts`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', api_access_token: CHATWOOT_API_TOKEN },
      body: JSON.stringify({
        inbox_id: CHATWOOT_ZALO_INBOX_ID,
        name: `Zalo User ${sender.id.slice(-6)}`,
        identifier: `zalo:${sender.id}`,
      }),
    });
    const createdJson: any = await created.json();
    contactId = createdJson?.payload?.contact?.id;
  }

  // 2. Tao Conversation (hoac lay phien dang mo) va day tin nhan incoming
  const convRes = await fetch(`${CHATWOOT_URL}/api/v1/accounts/${CHATWOOT_ACCOUNT_ID}/conversations`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', api_access_token: CHATWOOT_API_TOKEN },
    body: JSON.stringify({ source_id: `zalo:${sender.id}`, inbox_id: CHATWOOT_ZALO_INBOX_ID, contact_id: contactId }),
  });
  const convJson: any = await convRes.json();

  await fetch(`${CHATWOOT_URL}/api/v1/accounts/${CHATWOOT_ACCOUNT_ID}/conversations/${convJson.id}/messages`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', api_access_token: CHATWOOT_API_TOKEN },
    body: JSON.stringify({ content: message.text, message_type: 'incoming', source_id: `${message.msg_id}-${timestamp}` }),
  });

  return res.sendStatus(200);
});
